head.b:skin:
/* The Yellow Bottle — white / black, with a true dark mode. Shared by the preview and Blogger theme. */
:root {
  color-scheme: light;
  --paper: #fff;
  --ink: #080808;
  --quiet: #666;
  --quiet-2: #555;
  --line: #d5d5d5;
  --surface: #f3f3f3;
  --surface-hover: #f6f6f6;
  --accent: #d9a400;
  --sans: 'Manrope', 'Noto Sans Malayalam', Arial, sans-serif;
  --serif: 'EB Garamond', 'Noto Serif Malayalam', Georgia, serif;
  --reading-size: 23px;
  --gutter: clamp(20px, 4vw, 64px);
  --ease-panel: cubic-bezier(.77,0,.175,1);
  --ease-out: cubic-bezier(.2,.7,.2,1);
}
:root[data-theme='dark'] {
  color-scheme: dark;
  --paper: #0a0a0a;
  --ink: #f2f2f2;
  --quiet: #9c9c9c;
  --quiet-2: #aaa;
  --line: #2a2a2a;
  --surface: #161616;
  --surface-hover: #191919;
  --accent: #f2c230;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    color-scheme: dark;
    --paper: #0a0a0a;
    --ink: #f2f2f2;
    --quiet: #9c9c9c;
    --quiet-2: #aaa;
    --line: #2a2a2a;
    --surface: #161616;
    --surface-hover: #191919;
    --accent: #f2c230;
  }
}
:root { transition: color .2s ease; }
body { transition: background-color .2s ease, color .2s ease; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 88px; }
body { margin: 0; background: var(--paper); color: var(--ink); font: 400 14px/1.5 var(--sans); -webkit-font-smoothing: antialiased; }
body.menu-open { overflow: hidden; }
::selection { color: var(--paper); background: var(--ink); }
a { color: inherit; text-decoration: none; }
button, input { font: inherit; color: inherit; }
button { cursor: pointer; }
button, input { border-radius: 0; }
button { border: 0; background: transparent; }
button:disabled { opacity: .3; cursor: default; }
a, button { -webkit-tap-highlight-color: transparent; }
:focus-visible { outline: 2px solid currentColor; outline-offset: 5px; }
img, video { display: block; max-width: 100%; height: auto; }
svg { display: block; }
figure, h1, h2, h3, p { margin: 0; }
[hidden] { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.skip { position: fixed; left: 20px; top: -80px; background: var(--ink); color: var(--paper); padding: 14px 22px; z-index: 100; }
.skip:focus { top: 12px; }
.micro { font: 500 10px/1.6 var(--sans); letter-spacing: .11em; text-transform: uppercase; }
.muted { color: var(--quiet); }
.dot { display: inline-block; width: 6px; height: 6px; background: currentColor; border-radius: 50%; vertical-align: middle; }
.wrap { margin: 0 var(--gutter); }
.text-link { display: inline-flex; align-items: center; gap: 26px; min-height: 44px; font-size: 12px; border-bottom: 1px solid; }
.text-link .arrow, .row-arrow { display: inline-block; font-family: Arial, sans-serif; }
.site-header { height: 86px; margin: 0 var(--gutter); display: flex; gap: 28px; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--ink); position: relative; z-index: 12; background: var(--paper); }
.wordmark { font-size: 21px; font-weight: 800; letter-spacing: -.07em; line-height: .97; display: inline-flex; gap: 10px; align-items: center; }
.wordmark svg { width: 19px; height: 34px; }
.top-nav { display: flex; gap: 28px; align-items: center; }
.top-nav a, .top-nav button { font-size: 12px; padding: 14px 0; min-height: 44px; }
.icon-btn { width: 34px; height: 34px; display: grid; place-items: center; flex-shrink: 0; transition: transform .3s ease; }
.icon-btn svg { width: 17px; height: 17px; }
.search-icon { width: 17px; height: 17px; }
.theme-toggle svg { grid-area: 1/1; }
.theme-toggle .icon-sun { display: none; }
:root[data-theme='dark'] .theme-toggle .icon-moon { display: none; }
:root[data-theme='dark'] .theme-toggle .icon-sun { display: block; }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) .theme-toggle .icon-moon { display: none; }
  :root:not([data-theme='light']) .theme-toggle .icon-sun { display: block; }
}
.menu-toggle { display: flex; align-items: center; gap: 15px; }
.menu-icon { display: grid; gap: 4px; width: 17px; }
.menu-icon i { height: 1px; background: currentColor; width: 17px; transition: transform .2s ease, opacity .2s ease; }
.menu-open .menu-icon i:first-child { transform: translateY(5px) rotate(45deg); }
.menu-open .menu-icon i:nth-child(2) { opacity: 0; }
.menu-open .menu-icon i:last-child { transform: translateY(-5px) rotate(-45deg); }
.close-button svg { width: 15px; height: 15px; }
.progress { position: fixed; top: 0; left: 0; height: 3px; width: 100%; background: var(--ink); z-index: 50; transform: scaleX(0); transform-origin: left; }
.hero { --tab: 42px; display: flex; border-bottom: 1px solid var(--ink); min-height: 650px; container-type: inline-size; overflow: hidden; }
.panel { position: relative; display: flex; flex: 0 0 var(--tab); min-width: 0; overflow: hidden; transition: flex-grow .95s var(--ease-panel); }
.panel.is-active { flex-grow: 1; }
.panel + .panel::before { content: ''; position: absolute; z-index: 2; left: 0; top: 0; bottom: 0; width: 1px; background: var(--ink); }
.panel-tab { position: relative; flex: 0 0 var(--tab); width: var(--tab); display: flex; flex-direction: column; align-items: center; justify-content: space-between; padding: 29px 0; transition: background .3s, color .3s; }
.panel-tab .chapter-name { writing-mode: vertical-rl; transform: rotate(180deg); font-size: 12px; letter-spacing: .025em; white-space: nowrap; }
.panel-tab .rail-shape { position: absolute; left: 50%; top: 50%; translate: -50% -50%; width: 16px; height: 16px; transition: fill .4s ease; }
.panel-tab .rail-mark { width: 10px; height: 18px; }
.panel:not(.is-active) > .panel-tab:hover, .panel:not(.is-active) > .panel-tab:focus-visible { background: var(--ink); color: var(--paper); }
.panel.is-active > .panel-tab { cursor: default; }
.panel.is-active > .panel-tab .rail-shape { fill: currentColor; }
.panel-body { flex: none; width: calc(100cqw - 6 * var(--tab)); transition: opacity .6s ease .5s; }
.js .panel:not(.is-active) > .panel-body { opacity: 0; transition: opacity .25s ease; }
.hero-main { display: grid; grid-template-columns: minmax(0,1fr) clamp(300px,36vw,600px); grid-template-rows: auto 1fr auto; padding: 31px 35px 26px 28px; column-gap: 18px; }
.hero-topline { grid-column: 1/-1; display: flex; align-items: center; justify-content: space-between; align-self: start; gap: 20px; }
.hero-title { font-size: clamp(80px, 10.8vw, 175px); font-weight: 600; line-height: .84; letter-spacing: -.085em; align-self: center; padding: 18px 0 25px; }
.hero-title .prefix { display: block; font: italic 400 clamp(31px,3.6vw,51px)/1 var(--serif); letter-spacing: -.05em; margin: 0 0 17px 6px; }
.hero-title .word { display: block; }
.hero-title .word + .word { margin-top: 14px; }
.hero-art { align-self: center; position: relative; grid-row: 2; grid-column: 2; margin: -10px -10px 0 0; }
.hero-emblem { width: 100%; max-height: 270px; overflow: visible; }
.art-play { padding: 0; width: 100%; display: block; }
.art-play:focus-visible { outline-offset: 10px; }
.hero-bottom { grid-column: 1/-1; display: flex; align-items: flex-end; justify-content: space-between; gap: 30px; margin-top: 32px; }
.hero-description { font-size: 17px; line-height: 1.55; max-width: 305px; letter-spacing: -.025em; }
.round-link { width: 54px; height: 54px; border-radius: 50%; border: 1px solid var(--ink); display: grid; place-items: center; font: 24px Arial, sans-serif; transition: background .25s, color .25s; flex-shrink: 0; }
.round-link:hover, .round-link:focus-visible { background: var(--ink); color: var(--paper); }
.figure-frame { position: relative; display: block; width: 100%; aspect-ratio: 1; }
.figure-frame canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.figure-frame.is-live { cursor: pointer; }
.hero-figure { aspect-ratio: 1; }
.hero-figure .hero-emblem { width: 100%; height: 100%; }
.chapter-body { display: grid; grid-template-columns: minmax(0,1.1fr) minmax(0,.9fr); grid-template-rows: auto minmax(0,1fr); padding: 31px 0 0 28px; column-gap: clamp(24px,4vw,64px); }
.chapter-top { grid-column: 1/-1; display: flex; justify-content: space-between; gap: 20px; padding-right: 35px; }
.chapter-figure { align-self: center; justify-self: center; width: min(100%, 580px); margin: 12px 0; }
.chapter-copy { display: flex; flex-direction: column; justify-content: center; border-left: 1px solid var(--ink); padding: 30px 35px 40px clamp(24px,3vw,48px); }
.chapter-title { font-size: clamp(46px,5.4vw,90px); font-weight: 500; letter-spacing: -.065em; line-height: .98; }
.chapter-ml { font: 400 clamp(17px,1.5vw,22px)/1.6 'Noto Sans Malayalam', var(--sans); color: var(--quiet); margin: 12px 0 24px; }
.chapter-desc { font: 400 clamp(19px,1.55vw,23px)/1.5 var(--serif); max-width: 380px; margin-bottom: 30px; }
.chapter-copy .text-link { align-self: flex-start; }
.chapter-copy > * { transition: opacity .7s ease, transform .9s var(--ease-out); }
.panel.is-active .chapter-copy > :nth-child(1) { transition-delay: .55s; }
.panel.is-active .chapter-copy > :nth-child(2) { transition-delay: .63s; }
.panel.is-active .chapter-copy > :nth-child(3) { transition-delay: .71s; }
.panel.is-active .chapter-copy > :nth-child(4) { transition-delay: .79s; }
.js .panel:not(.is-active) .chapter-copy > * { opacity: 0; transform: translateY(22px); transition-duration: .2s; }
.edition-strip { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 20px 0; border-bottom: 1px solid var(--line); }
.edition-strip .languages { font-size: 11px; letter-spacing: .01em; }
.lead { padding: 76px 0 80px; display: grid; grid-template-columns: 1fr 1.02fr; gap: clamp(35px,7vw,105px); align-items: center; border-bottom: 1px solid var(--ink); }
.lead-art { min-height: 350px; height: 100%; background: var(--surface); display: grid; place-items: center; overflow: hidden; position: relative; }
.lead-art::after { content: 'FIG. 01 / AN OPEN FORM'; position: absolute; left: 22px; bottom: 18px; font: 9px var(--sans); letter-spacing: .12em; }
.lead-art svg { width: 70%; max-height: 300px; transition: transform .7s cubic-bezier(.2,.6,.2,1); }
.lead-art:hover svg { transform: scale(1.02); }
.lead-art.has-image::after { content: none; }
.lead-art img { width: 100%; height: 100%; object-fit: cover; position: absolute; }
.lead-copy h2 { font-weight: 500; font-size: clamp(40px,4.7vw,70px); line-height: 1.06; letter-spacing: -.055em; margin: 23px 0 22px; overflow-wrap: anywhere; }
.lead-copy p { font: 400 21px/1.5 var(--serif); color: var(--quiet-2); max-width: 460px; }
.lead-copy .text-link { margin-top: 23px; }
.lead-meta { display: flex; gap: 14px; flex-wrap: wrap; }
.writing { padding: 60px 0 0; scroll-margin-top: 25px; }
.section-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 25px; margin-bottom: 30px; }
.section-heading h2 { font-size: clamp(38px,4.5vw,64px); font-weight: 500; letter-spacing: -.065em; line-height: 1.1; }
.section-heading h2 em { font-family: var(--serif); font-weight: 400; }
.filters { display: flex; align-items: center; gap: 25px; padding: 0 0 19px; border-bottom: 1px solid var(--ink); flex-wrap: wrap; }
.filter { font: 400 11px/1.7 var(--sans); min-height: 40px; display: inline-flex; align-items: center; gap: 7px; padding: 6px 0; position: relative; }
.filter::before { content: ''; width: 5px; height: 5px; border-radius: 50%; background: transparent; }
.filter[aria-current='page']::before { background: currentColor; }
.post-row { display: grid; grid-template-columns: 44px minmax(0,1fr) 160px 28px; gap: 25px; padding: 30px 0; align-items: center; border-bottom: 1px solid var(--line); position: relative; transition: padding .3s, background .3s; }
.post-row:hover { background: var(--surface-hover); padding-left: 16px; padding-right: 16px; }
.post-row h3 { font-size: clamp(24px,2.55vw,37px); font-weight: 500; line-height: 1.27; letter-spacing: -.045em; overflow-wrap: anywhere; }
.post-row p { font: 18px/1.6 var(--serif); color: var(--quiet); margin-top: 9px; }
.post-row .post-meta { text-align: right; font-size: 9px; display: grid; gap: 8px; }
.post-row .row-arrow { font-size: 24px; text-align: right; }
.ml-title, :lang(ml).post-title { font-family: 'Noto Sans Malayalam', var(--sans); letter-spacing: -.025em; font-weight: 400; line-height: 1.6; }
.post-row h3.ml-title { font-size: clamp(23px,2.3vw,34px); }
.pagination { display: flex; align-items: center; gap: 30px; justify-content: space-between; border-top: 1px solid var(--ink); padding: 24px 0 0; flex-wrap: wrap; }
.pagination .text-link { border-bottom: 0; }
.pagination .older { margin-left: auto; }
.empty { padding: 50px 0; font: 28px/1.5 var(--serif); }
.empty a { text-decoration: underline; }
.about { margin-top: 85px; padding: 60px 0 65px; border-top: 1px solid var(--ink); display: grid; grid-template-columns: 1fr 1.6fr; gap: 60px; }
.about-copy h2 { font-size: clamp(40px,4.8vw,70px); line-height: 1.1; letter-spacing: -.06em; font-weight: 500; }
.about-copy h2 em { font-family: var(--serif); font-weight: 400; }
.about-copy p { margin-top: 22px; font-size: 15px; max-width: 450px; line-height: 1.8; }
.about-portrait { width: min(100%, 300px); aspect-ratio: 68 / 110; margin-top: 36px; }
.footer { margin: 0 var(--gutter); border-top: 1px solid var(--ink); padding: 30px 0 20px; }
.footer-top { display: flex; align-items: center; justify-content: space-between; gap: 25px; }
.footer-links { display: flex; gap: 25px; flex-wrap: wrap; font-size: 11px; }
.footer-links a { min-height: 44px; display: inline-flex; align-items: center; }
.footer-bottom { border-top: 1px solid var(--line); padding-top: 18px; display: flex; justify-content: space-between; align-items: center; gap: 25px; font-size: 9px; color: var(--quiet); }
.copyright { max-width: 820px; font-size: 10px; line-height: 1.85; color: var(--quiet-2); padding: 0 0 22px; }
.copyright a { text-decoration: underline; text-underline-offset: 3px; }
.footer-bottom a { min-height: 36px; display: inline-flex; align-items: center; }
.preview-note { border-bottom: 1px solid var(--line); padding: 10px 0; font-size: 10px; color: var(--quiet); }
.archive-items { display: flex; flex-wrap: wrap; gap: 10px 30px; list-style: none; padding: 15px 0 25px; margin: 0; }
.archive-items a { display: inline-block; padding: 9px 0; font-size: 12px; border-bottom: 1px solid var(--line); }
.overlay { position: fixed; z-index: 20; inset: 0; background: var(--paper); padding: 25px var(--gutter) 40px; overflow-y: auto; clip-path: inset(0 0 0 100%); transition: clip-path .85s var(--ease-panel); }
.overlay.is-open { clip-path: inset(0 0 0 0); }
.overlay .rise { opacity: 0; transform: translateY(28px); transition: opacity .2s ease, transform .2s ease, padding .3s ease; }
.overlay.is-open .rise { opacity: 1; transform: none; transition: opacity .7s ease calc(.4s + var(--i, 0) * 60ms), transform 1s var(--ease-out) calc(.4s + var(--i, 0) * 60ms), padding .3s ease 0s; }
body:has(#Blog1):not(:has([data-blog-rendered])) .about, body:has(#Blog1):not(:has([data-blog-rendered])) .footer { visibility: hidden; }
body:has(#Blog1):not(:has([data-blog-rendered])) main { min-height: 100vh; }
.js .reveal { opacity: 0; transform: translateY(20px); transition: opacity .9s ease calc(var(--d, 0) * 70ms), transform 1s var(--ease-out) calc(var(--d, 0) * 70ms); }
.js .reveal.is-in { opacity: 1; transform: none; }
.menu-gallery { display: grid; grid-template-columns: repeat(2, minmax(0, 150px)); gap: 26px 22px; margin-top: 40px; }
.menu-gallery figure { margin: 0; }
.menu-gallery figcaption { margin-top: 8px; font-size: 9px; }
.index-inner { display: grid; grid-template-columns: .8fr 1.2fr; gap: 60px; padding-top: 65px; }
.index-inner h2 { font-size: clamp(40px,6vw,86px); font-weight: 500; line-height: 1.05; letter-spacing: -.06em; margin: 20px 0 30px; }
.index-inner h2 em { font-family: var(--serif); font-weight: 400; }
.index-figure { width: min(100%, 260px); }
.index-list .archive-items { flex-direction: column; flex-wrap: nowrap; gap: 0; padding: 0; }
.index-list .archive-items a { display: flex; justify-content: space-between; gap: 20px; font-size: clamp(22px,2.4vw,34px); letter-spacing: -.04em; padding: 12px 0; border-bottom: 1px solid var(--line); }
.index-list .archive-items a .muted { font-size: 11px; letter-spacing: .04em; align-self: center; }
.index-list .archive-items a:hover { padding-left: 12px; }
.is-home .footer-top { display: none; }
.post-list, #post-list { counter-reset: row; }
.is-home .post-list:not([data-fallback]), .is-home #post-list { counter-reset: row 1; }
.post-row .row-no::before { counter-increment: row; content: counter(row, decimal-leading-zero); }
.overlay-top { display: flex; align-items: center; justify-content: space-between; padding-bottom: 20px; border-bottom: 1px solid; }
.close-button { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; font-size: 12px; padding: 10px 0 10px 25px; }
.overlay-grid { display: grid; grid-template-columns: .7fr 1.3fr; gap: 60px; padding-top: 65px; }
.menu-links { display: grid; }
.menu-links a { font-size: clamp(34px,5vw,72px); font-weight: 500; letter-spacing: -.055em; line-height: 1.25; border-bottom: 1px solid var(--line); display: flex; align-items: baseline; justify-content: space-between; padding: 12px 0; }
.menu-links a span { font-size: 10px; letter-spacing: .06em; font-weight: 400; }
.menu-links a:hover { padding-left: 12px; }
.menu-sub { display: flex; flex-wrap: wrap; gap: 20px; margin-top: 35px; }
.menu-sub a { font-size: 12px; padding: 10px 0; }
.search-inner { max-width: 940px; margin: 90px auto 0; }
.search-inner h2 { font-size: clamp(40px,7vw,90px); font-weight: 500; line-height: 1.1; letter-spacing: -.06em; margin-bottom: 50px; }
.search-form { display: flex; align-items: stretch; border-bottom: 1px solid var(--ink); gap: 20px; }
.search-form input { border: 0; background: var(--paper); color: var(--ink); font-size: clamp(21px,3vw,35px); width: 100%; min-width: 0; padding: 16px 0; }
.search-form button { flex: 0 0 60px; font-size: 32px; }
.search-inner p { margin-top: 20px; color: var(--quiet); font-size: 12px; }
.search-results { margin-top: 26px; max-height: 52vh; overflow-y: auto; }
.search-results a { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 4px 24px; padding: 16px 0; border-bottom: 1px solid var(--line); }
.search-results a:hover, .search-results a:focus-visible { background: var(--surface-hover); }
.search-results strong { font-size: 19px; font-weight: 500; letter-spacing: -.02em; }
.search-results small { grid-column: 1; color: var(--quiet); font-size: 13px; line-height: 1.5; }
.search-results time { grid-row: 1; grid-column: 2; font-size: 10px; letter-spacing: .06em; text-transform: uppercase; color: var(--quiet); }
.search-results mark { background: none; color: inherit; box-shadow: inset 0 -.45em 0 color-mix(in srgb, var(--accent) 45%, transparent); }
.search-results .search-all { display: block; border: 0; font-size: 12px; padding-top: 18px; }
.reader-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 32px 0; }
.reader-toolbar a { font-size: 11px; min-height: 44px; display: inline-flex; align-items: center; }
.type-controls { display: flex; align-items: center; gap: 0; }
.type-controls .micro { margin-right: 18px; }
.type-controls button { border: 1px solid var(--line); width: 44px; height: 44px; font-size: 13px; margin-left: -1px; }
.type-controls button:hover:enabled { color: var(--paper); background: var(--ink); }
.reading-page { max-width: 780px; margin: 40px auto 90px; }
.article-title { font-size: clamp(44px,6vw,80px); font-weight: 500; line-height: 1.06; letter-spacing: -.055em; margin: 24px 0 30px; overflow-wrap: anywhere; }
.article-title.ml-title { font-size: clamp(34px,4.5vw,60px); }
.article-deck { color: var(--quiet); font: italic 27px/1.5 var(--serif); margin: 0 0 28px; }
.article-byline { display: flex; gap: 20px; flex-wrap: wrap; justify-content: space-between; border-top: 1px solid var(--ink); border-bottom: 1px solid var(--line); padding: 19px 0; margin-bottom: 40px; font-size: 10px; }
.reading-page.has-glow { position: relative; isolation: isolate; }
.reader-glow { position: absolute; z-index: -1; top: -70px; left: -140px; right: -140px; pointer-events: none; -webkit-mask-image: radial-gradient(ellipse 58% 60% at 50% 48%, #000 25%, transparent 72%); mask-image: radial-gradient(ellipse 58% 60% at 50% 48%, #000 25%, transparent 72%); }
.reader-glow::before { content: ''; position: absolute; inset: 0; background: var(--img) center / cover no-repeat; filter: blur(22px) saturate(1.05); opacity: var(--glow, .3); }
:root[data-theme='dark'] .reader-glow { --glow: .2; }
@media (prefers-color-scheme: dark) { :root:not([data-theme='light']) .reader-glow { --glow: .2; } }
@media (max-width: 900px) { .reader-glow { left: -16px; right: -16px; } }
.reader-cover { margin: 0 0 44px; }
.reader-cover a, .reader-cover .separator { display: block; margin: 0 !important; padding: 0 !important; }
.reader-cover img { display: block; width: auto !important; max-width: 100% !important; max-height: 72vh; margin: 0 auto !important; object-fit: contain; }
@media (min-width: 1240px) {
  .reading-page.has-cover .reader-cover { position: absolute; top: 0; left: calc(100% + 56px); width: min(260px, calc((100vw - 780px) / 2 - 110px)); margin: 0; }
  .reading-page.has-cover .reader-cover img { width: 100% !important; max-height: 60vh; object-fit: cover; }
}
.article-body { font: 400 var(--reading-size)/1.8 var(--serif); overflow-wrap: anywhere; }
.article-body p, .article-body ul, .article-body ol { margin: 0 0 1.2em; }
.article-body h2, .article-body h3 { font: 500 1.35em/1.3 var(--sans); margin: 1.5em 0 .7em; letter-spacing: -.03em; }
.article-body a { text-decoration: underline; text-underline-offset: 3px; }
.article-body blockquote { margin: 40px 0; padding: 30px 0; border-block: 1px solid var(--ink); font-size: 1.55em; line-height: 1.35; font-style: italic; }
.article-body blockquote p { margin: 0; }
.article-body .poem { line-height: 2.2; }
.article-body:lang(ml), .article-body [lang='ml'] { font-family: 'Noto Serif Malayalam', serif; line-height: 2.2; }
.article-body img { height: auto !important; max-width: 100% !important; margin: 22px auto; }
.article-body iframe { max-width: 100%; }
.article-body iframe[src*='youtube'], .article-body iframe[src*='vimeo'] { width: 100%; height: auto; aspect-ratio: 16/9; }
.article-body .separator { max-width: 100%; }
.article-body pre { white-space: pre-wrap; overflow-wrap: anywhere; font-size: .7em; padding: 20px; background: var(--surface); }
.article-body table { display: block; max-width: 100%; overflow-x: auto; }
.article-labels { display: flex; flex-wrap: wrap; gap: 10px 20px; margin: 35px 0; font: 11px/1.6 var(--sans); }
.article-labels a { border-bottom: 1px solid var(--line); padding: 8px 0; }
.article-end { padding: 22px 0; border-block: 1px solid var(--ink); display: flex; justify-content: space-between; gap: 25px; align-items: center; font-size: 11px; }
.article-end button, .article-end a { min-height: 44px; }
.article-end a { display: flex; align-items: center; }
.post-actions { display: flex; align-items: center; gap: 14px; margin-left: auto; }
.like-button { display: inline-flex; align-items: center; gap: 4px; padding: 0 4px; }
.like-button svg { width: 44px; height: 44px; overflow: visible; stroke-linecap: round; }
.like-button line { stroke: currentColor; stroke-width: 1.3; transition: stroke .5s ease calc(var(--k) * 25ms), transform .5s var(--ease-out) calc(var(--k) * 25ms); transform-origin: 20px 20px; }
.like-button .ray { stroke: var(--c); stroke-dasharray: 1; stroke-dashoffset: 1; opacity: 0; }
.like-button.is-liked .rest { stroke: var(--c); stroke-width: 1.6; }
.like-button.is-bursting .ray { animation: ray .9s var(--ease-out) calc(var(--k) * 18ms) both; }
.like-button.is-bursting .rest { animation: rest-turn .9s var(--ease-out) both; }
@keyframes ray { 0% { opacity: 1; stroke-dashoffset: 1; } 55% { opacity: 1; stroke-dashoffset: 0; } 100% { opacity: 0; stroke-dashoffset: -1; } }
@keyframes rest-turn { 0% { transform: rotate(0) scale(1); } 40% { transform: rotate(15deg) scale(.7); } 100% { transform: rotate(30deg) scale(1); } }
.like-count { min-width: 1ch; font-size: 11px; letter-spacing: .04em; }
.share { position: relative; }
.share-button { display: inline-flex; align-items: center; gap: 9px; height: 40px; padding: 0 18px 0 14px; border-radius: 40px; background: #0b0b0b; color: #fff; border: 1px solid var(--ink); font: 500 11px/1 var(--sans); letter-spacing: .06em; text-transform: uppercase; }
.share-button svg { width: 17px; height: 17px; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.share-button:hover, .share-button:focus-visible { background: #262626; }
.share-menu { position: absolute; right: 0; bottom: calc(100% + 10px); z-index: 20; min-width: 190px; display: grid; background: var(--paper); border: 1px solid var(--ink); padding: 6px 0; }
.share-menu[hidden] { display: none; }
.share-menu a, .share-menu button { display: flex; justify-content: space-between; align-items: center; min-height: 40px; padding: 0 16px; font-size: 12px; text-align: left; width: 100%; }
.share-menu a:hover, .share-menu button:hover, .share-menu a:focus-visible, .share-menu button:focus-visible { background: var(--surface-hover); }
.comments h3 em { font-family: var(--serif); font-weight: 400; }
.comment-head { display: flex; justify-content: space-between; gap: 20px; align-items: baseline; }
.comments .comment.is-reply { margin-left: 30px; }
.comment-empty { margin-bottom: 10px; }
.comment-write { margin-top: 35px; }
.comment-write h4 { margin-bottom: 14px; }
.comment-open { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 0 22px; border: 1px solid var(--ink); border-radius: 44px; font-size: 13px; transition: background .25s, color .25s; }
.comment-open:hover, .comment-open:focus-visible { background: var(--ink); color: var(--paper); }
.comment-write p { margin-top: 12px; font-size: 10px; }
.post-rights { margin: 40px 0 26px; padding-top: 16px; border-top: 1px solid var(--line); font: 400 10px/1.7 var(--sans); letter-spacing: .02em; color: var(--quiet); }
.post-rights a { text-decoration: underline; text-underline-offset: 2px; }
.post-rights strong { font-weight: 600; color: var(--ink); }
.read-more { display: grid; grid-template-columns: 120px minmax(0,1fr); gap: 28px; align-items: center; margin-top: 45px; padding-bottom: 10px; }
.read-more-art { width: 120px; }
.read-more h2 { margin-bottom: 10px; }
.read-more ul { list-style: none; margin: 0; padding: 0; }
.read-more li + li { border-top: 1px solid var(--line); }
.read-more a { display: flex; justify-content: space-between; align-items: baseline; gap: 20px; padding: 11px 0; font-size: 15px; transition: color .25s; }
.read-more a:hover, .read-more a:focus-visible { color: var(--quiet); }
.read-more time { flex-shrink: 0; font-size: 9px; }
@media (max-width: 560px) { .read-more { grid-template-columns: 1fr; gap: 14px; } .read-more-art { width: 96px; } }
.comments { margin-top: 55px; font-size: 14px; }
.comments h3 { font-size: 26px; font-weight: 500; letter-spacing: -.04em; margin: 0 0 25px; }
.comments .comment { padding: 25px 0; border-bottom: 1px solid var(--line); }
.comment-body { padding: 12px 0; line-height: 1.8; }
.comment-footer, .comment-timestamp { font-size: 11px; }
.comment-form { margin-top: 30px; }
.comment-form iframe { width: 100%; border: 0; }
.comment-form h4 { font-weight: 500; }
.avatar-image-container { float: left; margin-right: 15px; }
.comments .footer { border: 0; margin: 0; padding: 15px 0; }
.comments .comment-replies { margin-left: 30px; }
.comments .comment-actions a { margin-right: 15px; }
.comments .comment-header { font-size: 12px; }
.reveal-in { animation: reveal .5s ease both; }
@keyframes reveal { from { opacity: 0; } to { opacity: 1; } }
@media (min-width: 1650px) { body { max-width: 1800px; margin: 0 auto; } }
@media (max-width: 1100px) {
  .hero { --tab: 38px; min-height: 590px; }
  .hero-main { grid-template-columns: minmax(0,1fr) 36vw; padding-right: 25px; }
  .hero-title { font-size: 9.2vw; }
  .chapter-body { grid-template-columns: minmax(0,1fr) minmax(0,1fr); }
  .chapter-copy { padding-right: 25px; }
  .hero-topline .micro:last-child { display: none; }
  .lead-art { min-height: 315px; }
  .post-row { grid-template-columns: 30px minmax(0,1fr) 125px 25px; gap: 20px; }
}
@media (max-width: 760px) {
  html { scroll-padding-top: 20px; }
  .site-header { height: 76px; }
  .top-nav { gap: 25px; }
  .top-nav .desktop-nav { display: none; }
  .wordmark { font-size: 19px; }
  .hero { display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); min-height: 0; container-type: normal; overflow: visible; }
  .panel { display: contents; }
  .panel + .panel::before { content: none; }
  .panel:first-child > .panel-tab, .chapter-body { display: none; }
  .js .hero .panel > .hero-main { opacity: 1; }
  .hero-main { grid-column: 1/-1; width: auto; grid-template-columns: minmax(0,1fr); padding: 26px 0 30px; gap: 15px; }
  .hero-title { font-size: clamp(85px,16vw,126px); padding: 14px 0 20px; }
  .hero-title .prefix { font-size: 34px; }
  .hero-art { grid-row: 3; grid-column: 1; justify-self: center; width: min(100%, 440px); margin: -6px 0 0; }
  .hero-bottom { margin-top: 13px; gap: 20px; }
  .hero-description { font-size: 14px; max-width: 250px; }
  .hero-aside { display: none; }
  .panel-tab { width: auto; min-width: 0; padding: 14px 5px; gap: 12px; border-top: 1px solid var(--ink); border-left: 1px solid var(--ink); }
  .panel:nth-child(2) > .panel-tab { border-left: 0; }
  .panel-tab .chapter-name { writing-mode: horizontal-tb; transform: none; font-size: 10px; white-space: normal; text-align: center; }
  .panel-tab .rail-shape { display: none; }
  .panel-tab .micro { font-size: 9px; }
  .edition-strip { padding: 15px 0; }
  .edition-strip .micro { font-size: 8px; }
  .edition-strip .languages { font-size: 9px; }
  .lead { grid-template-columns: minmax(0,1fr); gap: 28px; padding: 38px 0 43px; }
  .lead-art { min-height: 0; min-width: 0; width: 100%; height: auto; aspect-ratio: 1.3; }
  .lead-art svg { max-height: 230px; }
  .lead-copy h2 { font-size: 45px; max-width: 500px; margin: 18px 0; }
  .lead-copy p { font-size: 21px; }
  .writing { padding-top: 40px; }
  .section-heading { align-items: flex-start; }
  .section-heading .micro { font-size: 8px; max-width: 105px; text-align: right; }
  .filters { gap: 6px 21px; padding-bottom: 12px; }
  .filter { font-size: 10px; }
  .post-row { grid-template-columns: 25px minmax(0,1fr) 22px; gap: 13px; padding: 24px 0; }
  .post-row .post-meta { grid-column: 2; grid-row: 2; display: flex; text-align: left; font-size: 8px; gap: 14px; }
  .post-row .row-arrow { grid-column: 3; grid-row: 1; font-size: 20px; }
  .post-row p { font-size: 17px; }
  .post-row:hover { padding-left: 6px; padding-right: 6px; }
  .about { grid-template-columns: 1fr; gap: 35px; margin-top: 50px; padding: 35px 0 40px; }
  .about-portrait { width: min(100%, 220px); margin-top: 24px; }
  .about-copy p { font-size: 14px; }
  .footer-top { align-items: flex-start; }
  .footer-links { gap: 0 20px; justify-content: flex-end; max-width: 240px; font-size: 10px; }
  .footer-bottom { align-items: flex-start; font-size: 8px; }
  .footer-bottom .footer-credit { display: none; }
  .overlay-grid { grid-template-columns: 1fr; gap: 30px; padding-top: 35px; }
  .overlay-grid .menu-note { display: none; }
  .index-inner { grid-template-columns: 1fr; gap: 20px; padding-top: 35px; }
  .index-figure { display: none; }
  .menu-links a { font-size: 39px; }
  .search-inner { margin-top: 70px; }
  .search-inner h2 { margin-bottom: 30px; }
  .reader-toolbar { padding: 20px 0; }
  .type-controls .micro { display: none; }
  .reading-page { margin: 25px auto 55px; }
  .article-title { font-size: 48px; }
  .article-deck { font-size: 24px; }
  .article-body { font-size: calc(var(--reading-size) - 2px); line-height: 1.85; }
  .article-body blockquote { font-size: 1.4em; }
}
@media (max-width: 390px) {
  .hero-title { font-size: 21.5vw; }
  .hero-description { max-width: 220px; font-size: 13px; }
  .round-link { width: 44px; height: 44px; }
  .hero-topline .micro { font-size: 8px; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
@media print {
  .site-header, .hero, .edition-strip, .overlay, .reader-toolbar, .article-end, .post-actions, .read-more, .comments, .about, .footer, .progress, .article-labels { display: none !important; }
  .wrap { margin: 0; }
  .reading-page { margin: 0 auto; max-width: 100%; }
  .article-title { font-size: 30pt; }
  .article-body { font-size: 12pt; }
}
